/// Pre-computed summary row from the `story_summaries` Supabase table.
///
/// Generated by the Saturday / monthly / yearly background jobs.
/// Consumed by [StoryNotifier] to skip local AI generation when a server-side
/// summary is already available — zero extra AI cost for the app.
class StorySummary {
  final DateTime periodStart;
  final String periodType; // 'weekly' | 'monthly' | 'yearly'
  final String summary;
  final String? topMood;
  final String? topTheme;
  final int entryCount;
  final DateTime updatedAt;

  const StorySummary({
    required this.periodStart,
    required this.periodType,
    required this.summary,
    this.topMood,
    this.topTheme,
    this.entryCount = 0,
    required this.updatedAt,
  });

  factory StorySummary.fromJson(Map<String, dynamic> json) => StorySummary(
        periodStart: DateTime.parse(json['period_start'] as String),
        periodType: json['period_type'] as String? ?? 'weekly',
        summary: json['summary'] as String,
        topMood: json['top_mood'] as String?,
        topTheme: json['top_theme'] as String?,
        entryCount: (json['entry_count'] as num?)?.toInt() ?? 0,
        updatedAt: DateTime.parse(json['updated_at'] as String),
      );
}
